\set ON_ERROR_STOP on
-- backyrd:authorization-positive
-- backyrd:authorization-negative
begin;
create function pg_temp.assert(p_ok boolean,p_message text) returns void language plpgsql as $$ begin if p_ok is not true then raise exception 'scoped knowledge failed: %',p_message;end if;end $$;
create function pg_temp.id(p text) returns uuid language sql immutable as $$ select (substr(md5(p),1,8)||'-'||substr(md5(p),9,4)||'-4'||substr(md5(p),14,3)||'-8'||substr(md5(p),18,3)||'-'||substr(md5(p),21,12))::uuid $$;
create function pg_temp.expect_error(p_sql text,p_state text,p_message text) returns void language plpgsql as $$ declare code text;begin begin execute p_sql;exception when others then get stacked diagnostics code=returned_sqlstate;if code=p_state then return;end if;raise exception '%: received %',p_message,code;end;raise exception '%: unexpected success',p_message;end $$;
select set_config('app.world_knowledge_founder_authoring_enabled','on',true);
create temporary table experience_fixture(value jsonb);
insert into experience_fixture values ('{"contractVersion":"backyrd.world-knowledge.experience-profile@1.0","category":"RESTAURANT","properties":[],"areas":[{"id":"terrace","kind":"TERRACE","name":"Terrasse","properties":[{"key":"location.waterbody","label":null,"state":"KNOWN","value":"Rhein","conditions":{"weekdays":[],"dayparts":[],"event":null,"validFrom":null,"validUntil":null}}]}],"offers":[{"id":"lunch","kind":"LUNCH","name":"Mittagessen","areaIds":["terrace"],"properties":[],"prices":[{"label":"Menü","currency":"CHF","min":19,"max":25,"basis":"PER_PERSON","minimumAge":null,"maximumAge":null,"mandatoryFeesIncluded":true,"includes":"Hauptgericht","conditions":{"weekdays":[],"dayparts":[],"event":null,"validFrom":null,"validUntil":null}}],"schedule":[],"validFrom":null,"validUntil":null}],"reviewed":true}'::jsonb);
select pg_temp.assert(world_knowledge_private.experience_profile_valid_v2((select value from experience_fixture)),'valid profile rejected');
select pg_temp.assert(not world_knowledge_private.experience_profile_valid_v2(jsonb_set((select value from experience_fixture),'{reviewed}','false')),'unreviewed accepted');
select pg_temp.assert(not world_knowledge_private.experience_profile_valid_v2(jsonb_set((select value from experience_fixture),'{offers,0,areaIds}','["missing"]')),'dangling area accepted');
select pg_temp.assert(not world_knowledge_private.experience_profile_valid_v2(jsonb_set((select value from experience_fixture),'{offers,0,prices,0,min}','99')),'inverted price accepted');
select pg_temp.assert(not world_knowledge_private.experience_profile_valid_v2(jsonb_set((select value from experience_fixture),'{offers,0,prices,0,min}','1.001')),'fractional cents accepted');
select pg_temp.assert(not world_knowledge_private.experience_profile_valid_v2(jsonb_set((select value from experience_fixture),'{areas,0,properties,0,key}','"unexpected.key"')),'unknown property accepted');
select pg_temp.assert(not world_knowledge_private.experience_profile_valid_v2(jsonb_set((select value from experience_fixture),'{offers,0,validFrom}','"2026-02-30"')),'invalid date accepted');
select pg_temp.assert(not world_knowledge_private.experience_profile_valid_v2(jsonb_set((select value from experience_fixture),'{offers,0,validFrom}','"2027-01-01"')||jsonb_build_object('invalidExtra',1)),'extra top field accepted');
select pg_temp.assert(world_knowledge_private.attribute_value_valid_v7('backyrd.world-knowledge.registry@2.5','experience.profile','UNKNOWN','null'),'explicit unknown lost');
select pg_temp.assert((select registry_hash='c3016e37bc0bb178c390a01a55cf69fa8d8f748593e1a794d2b2f9d84e513cc3' from world_knowledge_private.registry_releases where registry_version='backyrd.world-knowledge.registry@2.3'),'historical registry changed');
create temporary table universal_fixture(value jsonb);
insert into universal_fixture values ('{"contractVersion":"backyrd.world-knowledge.experience-profile@1.0","category":"STAY","properties":[],"areas":[{"id":"room","kind":"ROOM","name":"Zimmer","properties":[]},{"id":"bar","kind":"LOUNGE","name":"Barraum","properties":[]}],"offers":[{"id":"sleep","kind":"OVERNIGHT_STAY","name":"OVERNIGHT_STAY","areaIds":["room"],"properties":[{"key":"stay.check_in","value":"15:00","label":null,"state":"KNOWN","conditions":{"weekdays":[],"dayparts":[],"event":null,"validFrom":null,"validUntil":null}},{"key":"stay.check_out","value":"11:00","label":null,"state":"KNOWN","conditions":{"weekdays":[],"dayparts":[],"event":null,"validFrom":null,"validUntil":null}}],"prices":[{"label":"Zimmer pro Nacht","currency":"CHF","min":160,"max":160,"basis":"PER_ROOM_NIGHT","minimumAge":null,"maximumAge":null,"mandatoryFeesIncluded":true,"includes":"Übernachtung","conditions":{"weekdays":[],"dayparts":[],"event":null,"validFrom":null,"validUntil":null}}],"schedule":[],"validFrom":null,"validUntil":null},{"id":"breakfast","kind":"BREAKFAST","name":"BREAKFAST","areaIds":["bar"],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"drinks","kind":"DRINKS","name":"DRINKS","areaIds":["bar"],"properties":[{"key":"participation.audience","value":"Öffentlich zugänglich","label":null,"state":"KNOWN","conditions":{"weekdays":[],"dayparts":[],"event":null,"validFrom":null,"validUntil":null}},{"key":"food.drink","value":"Wein","label":null,"state":"KNOWN","conditions":{"weekdays":[],"dayparts":[],"event":null,"validFrom":null,"validUntil":null}}],"prices":[],"schedule":[],"validFrom":null,"validUntil":null}],"reviewed":true}'::jsonb);
